a-quality plan for a fictional project"}, {"field": "development", "slug": "grant-writing-associate", "title": "Grant writing associate", "skill": "Proposal writing", "project": "Write a sample grant proposal with an evidence-based budget"}]$catalog$::jsonb;
begin
  for v in select * from jsonb_to_recordset(v_catalog)
    as x(field text,slug text,title text,skill text,project text)
  loop
    select id into strict v_field from public.career_fields where slug=v.field;
    insert into public.skills(slug,name,category)
      values(trim(both '-' from regexp_replace(lower(v.skill),'[^a-z0-9]+','-','g')),v.skill,v.field)
      on conflict(slug) do nothing;
    select id into strict v_skill from public.skills
      where slug=trim(both '-' from regexp_replace(lower(v.skill),'[^a-z0-9]+','-','g'));
    insert into public.career_paths(slug,title,summary,category,field_id,day_to_day,good_fit_if,sort_order)
      values(v.slug,v.title,
        'Explore '||lower(v.title)||' through '||lower(v.skill)||', a small practice project and feedback. Check the qualifications required for each role; regulated professions need the relevant approved training and registration.',
        v.field,v_field,
        array['Use '||lower(v.skill)||' to solve practical problems','Document decisions and check the quality of work','Work with colleagues and explain results'],
        array['You enjoy '||lower(v.skill),'You are willing to practise and learn from feedback'],v_order)
      on conflict(slug) do nothing;
    select id into strict v_path from public.career_paths where slug=v.slug;
    insert into public.career_path_skills(path_id,skill_id,importance) values(v_path,v_skill,'core') on conflict do nothing;
    -- Transferable skills supplement, and never replace, the role-specific skill.
    for v_other in select id from public.skills where slug in ('written-communication','problem-solving','research') loop
      insert into public.career_path_skills(path_id,skill_id,importance) values(v_path,v_other,'important') on conflict do nothing;
    end loop;
    insert into public.career_path_milestones(path_id,order_index,title,description,typical_semester)
      values(v_path,0,'Discover the role','Learn what the work involves and compare training routes.',1)
      on conflict(path_id,order_index) do update set title=excluded.title returning id into v_milestone;
    insert into public.career_path_tasks(milestone_id,order_index,title,type,points,est_minutes) values
      (v_milestone,0,'Read two role descriptions and note the recurring skills','skill',2,30),
      (v_milestone,1,'Check official qualification and training information','skill',2,30),
      (v_milestone,2,'Write what interests you about this direction','skill',2,20)
      on conflict(milestone_id,order_index) do nothing;
    insert into public.career_path_milestones(path_id,order_index,title,description,typical_semester)
      values(v_path,1,'Practise the foundations','Turn an introductory lesson into a worked example.',3)
      on conflict(path_id,order_index) do update set title=excluded.title returning id into v_milestone;
    insert into public.career_path_tasks(milestone_id,order_index,title,type,points,est_minutes,skill_id) values
      (v_milestone,0,'Choose an introductory lesson in '||lower(v.skill),'skill',2,30,v_skill),
      (v_milestone,1,'Complete a worked example and explain each step','skill',3,60,v_skill),
      (v_milestone,2,'Ask a teacher or peer to review your explanation','skill',2,30,null)
      on conflict(milestone_id,order_index) do nothing;
    insert into public.career_path_milestones(path_id,order_index,title,description,typical_semester)
      values(v_path,2,'Build and keep proof','Make a safe practice sample and explain what you learned.',5)
      on conflict(path_id,order_index) do update set title=excluded.title returning id into v_milestone;
    insert into public.career_path_tasks(milestone_id,order_index,title,type,points,est_minutes) values
      (v_milestone,0,v.project,'project',4,120),
      (v_milestone,1,'Improve the sample after feedback and keep a copy','project',3,60),
      (v_milestone,2,'Write a short reflection on your decisions and results','skill',2,30)
      on conflict(milestone_id,order_index) do nothing;
    v_order := v_order+1;
  end loop;
end $seed$;
